def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([7]), fmt([1, 1]), fmt([1, 2]), fmt([2, 1]), fmt([4, 4, 4, 4]), fmt([1, 2, 3, 4, 5]), fmt([5, 4, 3, 2, 1]),
             fmt([-10**9, 10**9, -10**9, 10**9]), fmt([3, 1, 2, 5, 1, 4, 6, 0])]
    for n in (3, 5, 8, 12, 20, 40):
        for _ in range(2):
            tests.append(fmt([rng.randint(-5, 5) for _ in range(n)]))
        tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(n)]))
    N = 100000
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(N)]))
    tests.append(fmt(sorted((rng.randint(-10**9, 10**9) for _ in range(N)), reverse=True)))
    tests.append(fmt(sorted(rng.randint(-10**9, 10**9) for _ in range(N))))
    tests.append(fmt([rng.randint(1, 3) for _ in range(N)]))
    tests.append(fmt([10**9] * N))
    return tests
